//! SKMEM-R-07: the Rust intention store, tick and ledger against what the
//! Python modules wrote and did (`tests/intent_parity/`, generated by
//! `gen_intent_parity.py`). Hermetic: no Python needed.
//!
//! With `SKMEM_PYTHON` naming an interpreter whose `PYTHONPATH` (via
//! `SKMEM_PYTHONPATH`) can import skmemory, the live cross-engine tests also
//! run: the two engines must agree on the lock file path and contend on it,
//! and each must load and re-dump what the other wrote byte for byte.

mod intent_common;

use intent_common::*;
use serde_json::{json, Value};
use skmem::intentions::tick::{self, run_tick, TickOptions};
use skmem::intentions::{
    merge_intentions, parse_due_at, transition, Intention, IntentionStore, PrefilterOpts,
};
use skmem::ledger::{self, sidecar, Ledger, Record};
use skmem::pytime::Dt;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

fn dt(s: &str) -> Dt {
    Dt::parse(s).unwrap_or_else(|| panic!("bad dt {s}"))
}

fn s(v: &Value) -> &str {
    v.as_str().unwrap()
}

fn open(base: &Path) -> IntentionStore {
    // Locks under the scratch dir, never the real runtime dir.
    IntentionStore::open_with(base, 30_000, Some(&base.join("..").join("locks"))).unwrap()
}

fn pristine_copy(tag: &str) -> (PathBuf, IntentionStore) {
    let d = scratch(tag);
    let base = d.join("base");
    copy_dir(&parity().join("py_store"), &base);
    let st = open(&base);
    st.reindex().unwrap();
    (base, st)
}

fn pristine_snap() -> Snap {
    let (base, st) = pristine_copy("pristine");
    drop(st);
    snapshot(&base)
}

#[test]
fn dumps_match_pydantic() {
    for d in expected()["dumps"].as_array().unwrap() {
        let i = Intention::from_json(s(&d["input"])).unwrap();
        assert_eq!(i.dump_indent2(), s(&d["indent2"]), "{}", d["input"]);
        assert_eq!(i.dump_compact(), s(&d["compact"]), "{}", d["input"]);
        // and the dump reloads to the same model
        assert_eq!(
            Intention::from_json(&i.dump_indent2())
                .unwrap()
                .dump_indent2(),
            i.dump_indent2()
        );
    }
}

