#[test]
fn transitions_match_python() {
    let cases = &expected()["transitions"];
    assert!(cases.as_array().unwrap().len() > 80);
    for c in cases.as_array().unwrap() {
        let i = Intention::from_json(s(&c["intention"])).unwrap();
        let now = c["now"].as_str().map(dt);
        let snooze = c["snooze"].as_str().map(dt);
        let r = transition(&i, s(&c["event"]), now, snooze);
        match (c.get("result"), c.get("error")) {
            (Some(want), _) => assert_eq!(r.unwrap().dump_indent2(), s(want), "{c}"),
            (_, Some(err)) => assert_eq!(r.unwrap_err().to_string(), s(err), "{c}"),
            _ => unreachable!(),
        }
    }
}

