// ---------------------------------------------------------------- ledger

fn ev_json(e: &ledger::Event) -> Value {
    let mut m = json!({
        "skill": e.skill, "version": e.version, "event": e.event, "at": e.at,
        "effect": e.effect, "session": e.session, "id": e.id,
    });
    if let Some(x) = &e.source {
        m["source"] = json!(x);
    }
    if let Some(x) = &e.missing {
        m["missing"] = json!(x);
    }
    m
}

fn ledger_copy(tag: &str) -> (PathBuf, Ledger) {
    let d = scratch(tag);
    let base = d.join("base");
    copy_dir(&parity().join("py_ledger"), &base);
    let l = Ledger::new(&base, Some("skap01"));
    (base, l)
}

